package com.college.hospitalmanagement;
import jakarta.persistence.*;import java.time.LocalDate;
@Entity @Table(name="bed_allocations") public class BedAllocation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) @JoinColumn(name="patient_id") private Patient patient;@ManyToOne(optional=false) @JoinColumn(name="bed_id") private Bed bed;@Column(nullable=false) private LocalDate admissionDate;private LocalDate dischargeDate;@Column(length=1000) private String notes;public Long getId(){return id;}public Patient getPatient(){return patient;}public Bed getBed(){return bed;}public LocalDate getAdmissionDate(){return admissionDate;}public LocalDate getDischargeDate(){return dischargeDate;}public String getNotes(){return notes;}public void setPatient(Patient v){patient=v;}public void setBed(Bed v){bed=v;}public void setAdmissionDate(LocalDate v){admissionDate=v;}public void setDischargeDate(LocalDate v){dischargeDate=v;}public void setNotes(String v){notes=v;}}
